<?php
require __DIR__ . '/_boot.php';
$id = admin_id($_GET['id'] ?? null, true); $product = ['name'=>'','description'=>'','price'=>'','stock_quantity'=>'0','category_id'=>'','image_path'=>'assets/images/rose-bouquet.jpg'];
if ($id) { $statement=db()->prepare('SELECT * FROM products WHERE id=?'); $statement->execute([$id]); $product=$statement->fetch(); if (!$product) abort_request(404,'Arrangement not found.'); }
$form = $_SESSION['_admin_product_form'] ?? []; unset($_SESSION['_admin_product_form']); $errors=[];
if (($form['id'] ?? null) === $id) { $product=array_replace($product,$form['old'] ?? []); $errors=$form['errors'] ?? []; }
$categories=db()->query('SELECT * FROM categories ORDER BY name')->fetchAll(); $pageTitle=$id ? 'Edit arrangement' : 'Add arrangement';
require dirname(__DIR__, 2) . '/templates/admin_header.php';
?>
<form class="panel admin-form" method="post" action="<?= e(url('/admin/actions/product-save.php')) ?>" novalidate><?= csrf_field() ?><?php if ($id): ?><input type="hidden" name="id" value="<?= $id ?>"><?php endif; ?>
<?php if ($errors): ?><div class="notice error" role="alert">Please check the marked fields.<?php admin_error($errors,'form'); ?></div><?php endif; ?>
<div class="form-grid"><div class="form-field full"><label for="name">Arrangement name</label><input id="name" name="name" maxlength="150" required value="<?= e($product['name']) ?>"><?php admin_error($errors,'name'); ?></div><div class="form-field full"><label for="description">Description</label><textarea id="description" name="description" rows="5" maxlength="5000" required><?= e($product['description']) ?></textarea><?php admin_error($errors,'description'); ?></div>
<div class="form-field"><label for="category_id">Category</label><select id="category_id" name="category_id" required><option value="">Choose a category</option><?php foreach ($categories as $category): ?><option value="<?= (int)$category['id'] ?>" <?= (string)$product['category_id'] === (string)$category['id'] ? 'selected' : '' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select><?php admin_error($errors,'category_id'); ?><?php if (!$categories): ?><a href="<?= e(url('/admin/category-edit.php')) ?>">Add a category first</a><?php endif; ?></div>
<div class="form-field"><label for="image_path">Flower photograph</label><select id="image_path" name="image_path"><?php foreach (admin_product_image_choices() as $path=>$label): ?><option value="<?= e($path) ?>" <?= $product['image_path'] === $path ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select><?php admin_error($errors,'image_path'); ?><small>Choose from the shop’s approved photographs.</small></div>
<div class="form-field"><label for="price">Price (PHP)</label><input id="price" name="price" inputmode="decimal" required placeholder="1500.00" value="<?= e($product['price']) ?>"><?php admin_error($errors,'price'); ?></div><div class="form-field"><label for="stock_quantity">Stock quantity</label><input id="stock_quantity" name="stock_quantity" type="number" min="0" max="1000000" step="1" required value="<?= e($product['stock_quantity']) ?>"><?php admin_error($errors,'stock_quantity'); ?></div></div>
<?php if ($id && empty($product['is_active'])): ?><p class="notice">This arrangement is archived. Editing it preserves its archived state.</p><?php endif; ?><div class="form-actions"><button class="button" type="submit">Save arrangement</button><a class="button secondary" href="<?= e(url('/admin/products.php')) ?>">Cancel</a></div></form>
<?php require dirname(__DIR__, 2) . '/templates/admin_footer.php'; ?>
